      "bigquery": "SELECT c.campaign_name, c.channel, SUM(p.spend) AS total_spend, SUM(p.revenue) AS total_revenue, ROUND(SUM(p.revenue) * 1.0 / SUM(p.spend), 2) AS roas FROM ad_campaigns c JOIN ad_performance_daily p ON c.campaign_id = p.campaign_id GROUP BY c.campaign_name, c.channel ORDER BY roas DESC, c.campaign_name ASC;",
      "mysql": "SELECT c.campaign_name, c.channel, SUM(p.spend) AS total_spend, SUM(p.revenue) AS total_revenue, ROUND(SUM(p.revenue) * 1.0 / SUM(p.spend), 2) AS roas FROM ad_campaigns c JOIN ad_performance_daily p ON c.campaign_id = p.campaign_id GROUP BY c.campaign_name, c.channel ORDER BY roas DESC, c.campaign_name ASC;"
